package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the retirement date from the body; refuses one that is not a calendar date. A blank date is left for
 *  the sheet's today. */
public class ValidateRetire {

    public record RetireRequest(String date) {
    }

    public void validate(@RequestBody(required = false) RetireRequest request, Out<RetireInput> body)
            throws InvalidPersonException {
        String date = request == null || request.date() == null ? "" : request.date().trim();
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + date);
            }
        }
        body.set(new RetireInput(parsed));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a person of the sheet by id. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        Long id;
        try {
            id = Long.valueOf(personId.trim());
        } catch (NumberFormatException e) {
            throw new PersonNotFoundException(personId);
        }
        personOut.set(repository.findByIdAndSheetId(id, sheetId.trim())
                .orElseThrow(() -> new PersonNotFoundException(personId)));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date given, or the sheet's today. */
public class ApplyRetire {
    public void apply(@Val RetireInput input, @Val Sheet sheet, @Val Person person, PersonRepository repository) {
        person.retire(input.date() != null ? input.date() : sheet.getToday(), sheet.getToday());
        repository.saveAndFlush(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the retirement, once it is saved. */
public class AuditPersonRetired {
    public void audit(@Val Person person, @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + person.getSheetId() + " by=" + AuditUser.decode(user)
                + " name=" + person.getName() + " from=" + person.getRetiredFrom());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.StatementRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, StatementRepository statements, PatronRepository patrons, PersonAliasRepository aliases,
            PersonGradeRepository grades, SheetRepository sheets, TreeNames tree,
            ObjectResponse<PersonResponse> response) {
        Sheet sheet = sheets.findById(person.getSheetId()).orElseGet(() -> new Sheet(person.getSheetId()));
        response.send(PersonResponse.from(person, statements.findByPersonIdOrderByIdAsc(person.getId()),
                patrons.findByPersonIdOrderByIdAsc(person.getId()),
                aliases.findByPersonIdOrderByIdAsc(person.getId()), grades.gradesOf(person), sheet.getToday(),
                tree.usedAround(sheet.getId())));
    }
}
package net.officefloor.hq.app.person;

/** A person form that cannot be saved: an empty name, a name already in use on the sheet, or a grade other than A, B or C. */
public class InvalidPersonException extends Exception {
    public InvalidPersonException(String message) {
        super(message);
    }
}
